'use strict';
(function(){
 const state=document.getElementById('state'),note=document.getElementById('state-note'),panel=document.getElementById('state-resources'),heading=document.getElementById('state-heading'),intro=document.getElementById('state-intro'),draft=document.getElementById('request-template'),download=document.getElementById('download-template'),print=document.getElementById('print-template');
 if(!state||!note||!panel||!heading||!intro||!draft||!download||!print)return;
 const rcfp='https://www.rcfp.org/open-government-guide/';
 const guideLink=document.getElementById('guide-link');
 // Preliminary official-source research only. Not an attorney-reviewed legal verification.
 const independentlyAuditedStates=new Set(['Vermont']);
 const enhancedReviewStates=new Set(['Louisiana','Kentucky','Iowa','Kansas','Illinois','Indiana','Hawaii','Idaho','Florida','Georgia','Connecticut','Delaware','Arkansas','Colorado','Alabama','Alaska','Arizona','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming']);
 const verified={Utah:{law:'Utah Government Records Access and Management Act (GRAMA), Utah Code Title 63G, Chapter 2',summary:'ELIGIBILITY/SUBMISSION: Anyone may request qualifying public records from the governmental entity holding them; identify records specifically and keep a copy of the request. RESPONSE: GRAMA establishes response deadlines and separate expedited processing and extraordinary-circumstance rules; confirm the current applicable period in § 63G-2-204 rather than assuming all requests have the same deadline. FEES/EXEMPTIONS: Classification, privacy, protected records and allowable charges affect access. REVIEW: Start with the entity chief administrative officer; further appeals may go to the Government Records Office director or district court, depending on the statutory path. The 2026 § 63G-2-403 version generally gives 30 days to appeal the decision to the director, subject to specific exceptions and mediation tolling.',links:[['Utah Archives — GRAMA request and appeal FAQ','https://archives.utah.gov/transparency-services/government-records-access/faq/'],['Utah Legislature — 2026 appeal statute','https://le.utah.gov/xcode/title63g/chapter2/C63G-2-S403_2026050620260506.pdf']]},Vermont:{law:'Vermont Public Records Act, 1 V.S.A. §§ 315–320',summary:'AUDIT CHECKED 2026-11-19 AGAINST VERMONT LEGISLATURE STATUTES. ELIGIBILITY/SUBMISSION: Any person may inspect or copy public agency records under 1 V.S.A. § 316(a); identify records to the custodian. State inspection hours are specified in § 316(a)(1); local governments use customary business hours. RESPONSE: Under § 318(a), promptly ordinarily means immediately and not more than three business days, subject to exceptions. For active-use or stored records, § 318(b)(1) requires written certification and availability appointment within one calendar week. Unusual circumstances can affect timing; failure to comply with applicable limits constitutes deemed denial. FEES: § 316(b)-(e) allows actual copying and transmission costs and limited staff-time charges, generally where directly involved time exceeds 30 minutes or special creation/format conditions apply. Request an estimate; prepayment may be required. EXEMPTIONS: § 317(c)(5) protects qualifying criminal-investigation records where specified harms apply; other confidentiality and privacy exemptions may apply. § 318(e) requires release of segregable nonexempt material with redactions explained. APPEALS: Under § 318(c), appeal a custodian denial to the agency head, who generally must decide in writing within five business days; § 319(a) permits a civil Superior Court action and § 319(d) addresses costs. OPEN CHECKS: Agency-specific fees, court filing limits and record-specific confidentiality laws. Legislature calls its online compilation unofficial.',links:[['Vermont Legislature — § 316 eligibility and fees','https://legislature.vermont.gov/statutes/section/01/005/00316'],['Vermont Legislature — § 317 exemptions','https://legislature.vermont.gov/statutes/section/01/005/00317'],['Vermont Legislature — § 319 court review','https://legislature.vermont.gov/statutes/section/01/005/00319'],['Vermont Legislature — § 318 procedure and appeals','https://legislature.vermont.gov/statutes/section/01/005/00318'],['Vermont Legislature — Public Records Act chapter','https://legislature.vermont.gov/statutes/fullchapter/01/005']]},Virginia:{law:'Virginia Freedom of Information Act, Va. Code § 2.2-3700 et seq.',summary:'ELIGIBILITY: Access is generally available to Virginia citizens and qualifying media representatives; agencies may require a requester name and legal address. RESPONSE: § 2.2-3704 generally requires a response within five working days; an appropriate written notice may extend the period by seven working days. Criminal-investigative-file requests under § 2.2-3706.1 may have a different 60-working-day extension. FEES/EXEMPTIONS: Actual-cost charges and exemptions for personnel, law-enforcement and other records may apply. REVIEW: Enforcement can involve court proceedings under § 2.2-3713; verify remedies and deadlines before filing.',links:[['Virginia Legislature — § 2.2-3704 current text','https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3704/'],['Virginia FOIA Advisory Council — 2026 public records guide','https://foiacouncil.dls.virginia.gov/ref/Access%20to%20Public%20Records%202026%20DOCUMENT.html']]},Washington:{law:'Washington Public Records Act, RCW Chapter 42.56',summary:'ELIGIBILITY/SUBMISSION: Anyone may request identifiable, nonexempt public records from the appropriate agency. RESPONSE: RCW 42.56.520 requires an initial response within five business days, which may provide records, a link, an estimated timeframe, a clarification request, or a denial; it is not a universal five-day production deadline. FEES/EXEMPTIONS: Copying fees, personal privacy, personnel and investigative exemptions may apply. REVIEW: Denials require written reasons; judicial review under RCW 42.56.550 has a one-year filing provision measured from the agency claim of exemption or last installment production. Verify accrual and other procedural rules for a particular dispute.',links:[['Washington Legislature — response requirements','https://app.leg.wa.gov/Rcw/default.aspx?cite=42.56.520'],['Washington Legislature — judicial review','https://app.leg.wa.gov/RCW/default.aspx?Cite=42.56.550'],['Washington Legislature — full public records chapter','https://app.leg.wa.gov/RCW/default.aspx?cite=42.56&full=true']]},'West Virginia':{law:'West Virginia Freedom of Information Act, W. Va. Code § 29B-1-1 et seq.',summary:'ELIGIBILITY/SUBMISSION: Every person may request qualifying public records directly from the custodian; describe the records with reasonable specificity. RESPONSE: § 29B-1-3 generally requires the custodian, as soon as practicable and within five days excluding weekends and legal holidays, to furnish copies, offer inspection, or deny in writing with reasons. FEES/EXEMPTIONS: Actual reproduction costs may be charged, but search/retrieval labor charges are barred under § 29B-1-3(e); statutory privacy and other exemptions apply. REVIEW: A denial may be challenged for injunctive or declaratory relief in circuit court in the county where records are kept. Preserve the denial and seek advice about timing.',links:[['West Virginia Legislature — § 29B-1-3','https://code.wvlegislature.gov/29B-1-3/'],['West Virginia Legislature — full FOIA chapter','https://code.wvlegislature.gov/pdf/29B-1/']]},Wisconsin:{law:'Wisconsin Public Records Law, Wis. Stat. §§ 19.31–19.39',summary:'ELIGIBILITY/SUBMISSION: Any requester may ask the records authority for identifiable records; no special form is generally required. RESPONSE: § 19.35(4)(a) requires a response as soon as practicable and without delay, NOT a fixed number of days. FEES/EXEMPTIONS: Actual permissible copying charges apply; locating fees generally require at least $50 in location costs and advance payment may be required for charges above $5. Wisconsin also applies statutory exceptions and a public-interest balancing test. REVIEW: A requester can seek mandamus in court or ask the district attorney or Attorney General to pursue enforcement under § 19.37; those offices are not required to take every case.',links:[['Wisconsin DOJ — public records FAQ and enforcement','https://www.wisdoj.gov/Pages/AboutUs/public-records.aspx'],['Wisconsin DOJ — compliance guide','https://www.wisdoj.gov/Open%20Government/PRL_guide.pdf']]},Wyoming:{law:'Wyoming Public Records Act, Wyo. Stat. §§ 16-4-201–205',summary:'ELIGIBILITY/SUBMISSION: Any person may request public records from the designated public-records person of the governmental entity holding them. RESPONSE: § 16-4-202 provides for immediate release of readily available records when practicable; certain notices must be sent within seven business days; generally records must be released within 30 calendar days unless good cause prevents it. FEES/EXEMPTIONS: Reasonable electronic production costs, security and confidential-record exceptions may apply. REVIEW: The Governor’s Public Records Ombudsman can mediate and address certain disputes but does not give binding legal advice; district court remedies also exist. Confirm current law and any good-cause extension before taking action.',links:[['Wyoming Governor — Public Records Ombudsman','https://governor.wyo.gov/contact/public-records-ombudsman'],['Wyoming RCFP — statute and enforcement overview','https://www.rcfp.org/open-government-guide/wyoming/']]},'South Dakota':{law:'South Dakota Codified Laws Chapter 1-27, especially §§ 1-27-1 and 1-27-35–43',summary:'ELIGIBILITY: South Dakota residents and other persons interested in examining public records may inspect qualifying records. SUBMISSION: An informal request can be made to the custodian; after denial, submit a written request to the public record officer. RESPONSE: For that formal written request, the officer must provide records, deny with reasons, or acknowledge and estimate additional time within ten business days; failure to respond can be a deemed denial. FEES/EXEMPTIONS: Reasonable specialized-service fees, privacy, criminal investigation and other statutory exemptions apply; estimates may be required. REVIEW: A requester may generally initiate a civil action or Office of Hearing Examiners review within 90 days of denial. Confirm exact timing and filing procedures before acting.',links:[['South Dakota Legislature — Chapter 1-27','https://www.sdlegislature.gov/Statutes/1-27'],['South Dakota Attorney General — public records and disputes','https://atg.sd.gov/legal/opengovernment/publicrecords.aspx']]},Tennessee:{law:'Tennessee Public Records Act, Tenn. Code Ann. §§ 10-7-501 et seq.',summary:'ELIGIBILITY: The Act generally grants access to Tennessee citizens; agency policies and statutory exceptions affect eligibility and proof of citizenship. SUBMISSION: Contact the records custodian under the agency’s published policy; requests for inspection and copies may have different procedural requirements. RESPONSE: If prompt production is impracticable, the custodian must within seven business days provide the records, deny in writing with a basis, or give a written explanation of the time reasonably needed. FEES/EXEMPTIONS: Inspection generally is free; copies may incur permitted copying and labor charges, and confidential records remain protected. REVIEW: Denials may be challenged by petition in circuit or chancery court under § 10-7-505; seek advice promptly about deadlines.',links:[['Tennessee Comptroller — Public Records Act FAQ','https://comptroller.tn.gov/office-functions/open-records-counsel/open-meetings/frequently-asked-questions/tennessee-public-records-act-faqs.html'],['Tennessee Department of General Services — request procedures','https://www.tn.gov/generalservices/about-dgs/public-records-requests.html']]},Texas:{law:'Texas Public Information Act, Tex. Gov’t Code Chapter 552',summary:'ELIGIBILITY: Any person may request qualifying public information from a governmental body; written requests are important to trigger statutory procedures. SUBMISSION: Direct the request to the governmental body using an accepted method and sufficiently identify existing records. RESPONSE: Records must be produced promptly; ten business days is generally the deadline for an agency seeking to withhold records to request an Attorney General decision, NOT a universal production deadline. If production will exceed ten business days, the body generally must give a date. FEES/EXEMPTIONS: Statutory cost rules and confidentiality exceptions apply, including law-enforcement records. REVIEW: The Attorney General handles many withholding rulings and compliance complaints; court remedies may also exist. For a withholding ruling, agency submissions have additional 15-business-day requirements.',links:[['Texas Legislature — Government Code Chapter 552','https://tcss.legis.texas.gov/Docs/GV/htm/GV.552.htm'],['Texas Attorney General — Public Information Act overview','https://www.oag.state.tx.us/open-government/members-public/overview-public-information-act'],['Texas Attorney General — 2026 PIA Handbook','https://www.texasattorneygeneral.gov/sites/default/files/files/divisions/open-government/PIA-Handbook-2026.pdf']]},Oregon:{law:'Oregon Public Records Law, ORS 192.311–192.478',summary:'ELIGIBILITY: Any person may request nonexempt public records from the public body holding them; follow that body’s written request procedure. RESPONSE: ORS 192.324 generally requires acknowledgement or completion within five business days after a properly routed written request; ORS 192.329 requires completion as soon as practicable without unreasonable delay, subject to statutory exceptions. FEES/EXEMPTIONS: Actual-cost fees and potential public-interest waivers; criminal-investigation, privacy and attorney-client exemptions may apply. REVIEW: State-agency denials generally go to the Attorney General, local-body denials to the county district attorney, while denials by elected officials may require direct circuit-court action. Verify the specific appeal route before acting.',links:[['Oregon Legislature — ORS Chapter 192','https://www.oregonlegislature.gov/bills_laws/ors/ors192.html'],['Oregon DOJ — records law, fees and exemptions','https://www.doj.state.or.us/oregon-department-of-justice/public-records/public-records-and-meetings-law/'],['Oregon DOJ — denial appeals','https://www.doj.state.or.us/oregon-department-of-justice/public-records/appeal-a-state-agency-public-records-denial/']]},Pennsylvania:{law:'Pennsylvania Right-to-Know Law, 65 P.S. §§ 67.101–67.3104',summary:'ELIGIBILITY/SUBMISSION: Submit a sufficiently specific written request to the relevant Agency Open Records Officer; use the agency’s accepted submission method. RESPONSE: Normally five business days, with written interim extension allowed on statutory grounds; an extension beyond the permitted period may require requester agreement. FEES/EXEMPTIONS: Copying charges and exempt categories apply; some law-enforcement records follow distinct appeal rules. APPEAL: Many denials or deemed denials can be appealed to the Office of Open Records within 15 business days; exceptions apply to particular agencies and criminal-investigative records. Preserve the original request and denial.',links:[['Pennsylvania — official Right-to-Know instructions','https://www.pa.gov/services/ddap/file-a-right-to-know-request'],['Pennsylvania Office of Administration — response and appeals','https://www.pa.gov/agencies/oa/contact-us/right-to-know-law']]},'Rhode Island':{law:'Rhode Island Access to Public Records Act, R.I. Gen. Laws § 38-2-1 et seq.',summary:'ELIGIBILITY/SUBMISSION: Request reasonably identifiable nonexempt public records from the appropriate public body using its published APRA procedures. RESPONSE: Generally ten business days, with up to twenty additional business days for good cause. FEES/EXEMPTIONS: Copy and search charges and statutory exemptions may apply. APPEAL: A denial can be reviewed by the public body’s chief administrative officer, followed by a complaint to the Attorney General; Superior Court is another potential remedy. Verify the statute and applicable review deadlines before proceeding.',links:[['Rhode Island DHS — APRA response, fees and review','https://dhs.ri.gov/public-records'],['Rhode Island General Laws — Title 38, Chapter 2','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/INDEX.htm']]},'South Carolina':{law:'South Carolina Freedom of Information Act, S.C. Code §§ 30-4-10 et seq.',summary:'ELIGIBILITY/SUBMISSION: A person may make a written request to a public body for nonexempt records; some specified categories are available for in-person inspection without a written request. RESPONSE: The body generally must issue a determination within ten working days, or twenty working days if records are over 24 months old. If granted, production generally follows within 30 calendar days, or 35 for older records, with special deposit timing and written-extension rules. FEES/EXEMPTIONS: Reasonable fees, privacy, law-enforcement and personnel-related exemptions may apply. REVIEW: Statutory court enforcement provisions include eligibility and time-limit conditions; do not assume an administrative appeal.',links:[['South Carolina Legislature — FOIA Chapter 4','https://www.scstatehouse.gov/code/t30c004.php'],['South Carolina Legislature — archived statutory text for cross-check','https://www.scstatehouse.gov/Archives/CodeofLaws2024/t30c004']]},'New York':{law:'New York Freedom of Information Law (FOIL), Public Officers Law Article 6, §§ 84–90',summary:'FOIL covers records held by New York state and local government agencies, subject to exemptions. Send a reasonably described request to the agency holding the records. The New York Attorney General explains that agencies need not create records or provide legal research. Check agency acknowledgement, denial and appeal requirements in the current law. RESPONSE / PROCEDURAL CHECK: New York FOIL generally requires acknowledgment or response within five business days; appeal periods and acknowledgment estimates matter. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New York Attorney General — make a FOIL request','https://ag.ny.gov/i-want/make-foil-request'],['New York Office of Mental Health — FOIL guidance','https://omh.ny.gov/omhweb/foil/index.html']]},'North Carolina':{law:'North Carolina Public Records Law, N.C. Gen. Stat. Chapter 132',summary:'Any person may inspect and obtain copies of qualifying public records. North Carolina generally requires copies as promptly as possible rather than imposing one universal numerical response deadline. Requests need no special form; actual copying costs and certain permitted service charges may apply. Agency-specific confidential-record exemptions still matter. RESPONSE / PROCEDURAL CHECK: North Carolina generally requires production as promptly as possible; there is no single universal numerical deadline. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['North Carolina Legislature — § 132-1','https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-1.html'],['North Carolina Judicial Branch — public records FAQ','https://www.nccourts.gov/services/request-a-public-record/about-north-carolina-public-records-law'],['North Carolina DOJ — open government','https://ncdoj.gov/open-government/']]},'North Dakota':{law:'North Dakota Constitution Art. XI § 6; N.D.C.C. § 44-04-18 et seq.',summary:'Anyone, regardless of residency, may request reasonably identified public-entity records by phone, email, mail or in person; a written request is not generally required. A public entity must respond within a reasonable time, which varies with the request, and provide the legal basis for any denial. The Attorney General offers guidance and an open-records opinion process. RESPONSE / PROCEDURAL CHECK: North Dakota generally requires a response within a reasonable time; the Attorney General offers an open-records opinion process. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['North Dakota Attorney General — requesting records','https://attorneygeneral.nd.gov/open-records-meetings/requesting-public-records'],['North Dakota Attorney General — open records and meetings','https://attorneygeneral.nd.gov/open-records-meetings/'],['North Dakota Attorney General — 2026 manual','https://attorneygeneral.nd.gov/wp-content/uploads/2026/08/Open-Records-Manual-2026-1.pdf']]},Ohio:{law:'Ohio Public Records Act, Ohio Rev. Code § 149.43',summary:'Ohio generally allows any person to request public records without identifying themselves or explaining why, subject to specific statutory exceptions. Requests may be oral or written and must reasonably identify existing records. Records are to be made available promptly or within a reasonable period; consult the Attorney General Sunshine Laws Manual for exceptions and remedies. RESPONSE / PROCEDURAL CHECK: Ohio generally requires prompt inspection and copies within a reasonable time; Court of Claims and mandamus procedures differ. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Ohio Attorney General — Sunshine Laws Manual','https://www.ohioattorneygeneral.gov/Legal/Sunshine-Laws/The-Sunshine-Laws-Manual'],['Ohio Attorney General — 2026 Sunshine Manual','https://ohioattorneygeneral.gov/Files/Publications-Files/Publications-for-Legal/Sunshine-Laws-Publications/2025-Sunshine-Manual.aspx']]},Oklahoma:{law:'Oklahoma Open Records Act, 51 O.S. §§ 24A.1 et seq.',summary:'Oklahoma public-records requests are directed to the public body maintaining the records. The Oklahoma Attorney General publishes agency-specific procedures; its 2026 guidance requires use of its own request form for records held by that office, not necessarily other agencies. Exemptions, copying costs and reasonable access rules vary by record and custodian. RESPONSE / PROCEDURAL CHECK: Oklahoma generally requires prompt, reasonable access; there is no universal fixed numerical production deadline. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Oklahoma Attorney General — 2026 request instructions','https://oklahoma.gov/content/dam/ok/en/oag/open-records/2026.02.05%20-%20ORA%20Info%20Sheet%20and%20Form_Reader%20Extended.pdf']]},Nebraska:{law:'Nebraska Public Records Statutes, Neb. Rev. Stat. §§ 84-712–84-712.09',summary:'Nebraska allows public-records inspection or written requests to the government office holding records. Exemptions include certain medical, law-enforcement and security records. The Attorney General can review some denial disputes, and court relief may be available. RESPONSE / PROCEDURAL CHECK: Nebraska generally requires a response within four business days, with written explanations for delay. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Nebraska state public-records overview','https://statespending.nebraska.gov/PublicRecordsLaw'],['Nebraska Governor — request procedures','https://governor.nebraska.gov/public-records-request']]},Nevada:{law:'Nevada Public Records Act, NRS Chapter 239',summary:'Nevada law provides public-record access subject to exceptions. NRS 239.0107 generally requires agency action within five business days, which may include a written estimate rather than immediate production. NRS 239.011 provides a judicial remedy for qualifying denials, delays or fee disputes. RESPONSE / PROCEDURAL CHECK: Nevada generally requires a response within five business days; review § 239.0107 for available response options. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Nevada Legislature — Chapter 239','https://www.leg.state.nv.us/nrs/NRS-239.html'],['Nevada Department of Administration — requests','https://www.admin.nv.gov/public-records-requests/']]},'New Hampshire':{law:'New Hampshire Right-to-Know Law, RSA Chapter 91-A',summary:'New Hampshire RSA 91-A governs access to government records and meetings. Under RSA 91-A:4, if records are not immediately available, agencies generally must produce, deny or acknowledge with an estimated timeframe within five business days. Personnel and other exemptions may apply. RESPONSE / PROCEDURAL CHECK: New Hampshire generally requires access, denial, or written acknowledgment within five business days; verify the statute and case law. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New Hampshire government — right-to-know guide','https://www.governor.nh.gov/sites/g/files/ehbemt336/files/documents/right-to-know-law-presentation.pdf'],['New Hampshire municipal statutory text and guidance','https://www.weare.nh.gov/town-administrator/files/request-for-public-materials-under-rsa-91-a-right-to-know-law']]},'New Jersey':{law:'New Jersey Open Public Records Act, N.J.S.A. 47:1A-1 et seq.',summary:'New Jersey OPRA governs access to government records, with exemptions and administrative denial-review procedures. The Government Records Council publishes guidance, request forms and complaint processes. Confirm current procedures following statutory amendments. RESPONSE / PROCEDURAL CHECK: New Jersey OPRA has important recent amendments; response periods, request forms, and Government Records Council procedures require current-law review. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New Jersey Government Records Council','https://nj.gov/grc/'],['New Jersey Department of Community Affairs — OPRA','https://www.nj.gov/dca/home/opra.shtml']]},'New Mexico':{law:'New Mexico Inspection of Public Records Act, NMSA 1978 §§ 14-2-1–14-2-12',summary:'New Mexico IPRA generally allows oral or written requests, but statutory procedures and penalties apply to written requests. Official guidance identifies required requester contact details and a general 15-calendar-day inspection period, with intermediate notice requirements and exceptions. RESPONSE / PROCEDURAL CHECK: New Mexico IPRA generally has a 15-calendar-day inspection period and a three-business-day written acknowledgment rule. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New Mexico Department of Justice — IPRA','https://nmag.gov/get-help/inspection-of-public-records-act/'],['New Mexico Secretary of State — IPRA','https://www.sos.nm.gov/legislation-and-lobbying/legal-resources/ipra-request-information/']]},Maine:{law:'Maine Freedom of Access Act, 1 M.R.S. §§ 400–414',summary:'Maine FOAA requests go directly to the agency holding the records. The state says no special form or written request is required, although written requests help preserve a record. The Public Access Ombudsman can mediate disputes; court remedies have separate requirements. RESPONSE / PROCEDURAL CHECK: Maine generally requires a written acknowledgment within five working days and a good-faith reasonable-time estimate. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Maine government — making a FOAA request','https://www.maine.gov/foaa/request/'],['Maine government — FOAA FAQ','https://www.maine.gov/foaa/faq/index.shtml'],['Maine Public Access Ombudsman','https://www.maine.gov/foaa/ombudsman/index.htm']]},Maryland:{law:'Maryland Public Information Act, Md. Code General Provisions §§ 4-101–4-601',summary:'Maryland PIA requests go to the custodian of the agency holding the records. Maryland distinguishes access by a person in interest from general public access in some situations. The independent Ombudsman helps mediate disputes, and some complaints may proceed to the PIA Compliance Board after attempted mediation. RESPONSE / PROCEDURAL CHECK: Maryland PIA generally requires production or denial within 30 days, with a ten-working-day notice if production will take longer. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Maryland Attorney General — Public Information Act','https://oag.maryland.gov/resources-info/Pages/public-information-act.aspx'],['Maryland Attorney General — October 2026 PIA Manual','https://oag.maryland.gov/resources-info/Pages/pia-manual.aspx'],['Maryland Attorney General — PIA FAQ','https://oag.maryland.gov/resources-info/Pages/public-information-act-faq.aspx']]},Mississippi:{law:'Mississippi Public Records Act, Miss. Code Ann. §§ 25-61-1 et seq.',summary:'The Mississippi Ethics Commission accepts public-records complaints, mediates disputes and can conduct hearings and issue orders. Its official site provides model rules, a link to the Act and a complaint form. Requesters should preserve any written denial. RESPONSE / PROCEDURAL CHECK: Mississippi generally requires production or denial within seven working days unless the requester and custodian agree otherwise. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Mississippi Ethics Commission — Public Records Act','https://www.ethics.ms.gov/publicrecords']]},Missouri:{law:'Missouri Sunshine Law, Mo. Rev. Stat. Chapter 610',summary:'Missouri public-records requests should be directed to the custodian of the public body that maintains the records. The Attorney General says no particular request format is required but recommends writing; the office also provides sample forms and a complaint process. RESPONSE / PROCEDURAL CHECK: Missouri Sunshine Law generally requires a response within three business days; more time may be reasonable with explanation. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Missouri Attorney General — Sunshine Law','https://ago.mo.gov/get-help/programs-services-from-a-z/sunshine-law/']]},Montana:{law:'Montana Constitution Art. II, §§ 9–10; Montana public-records statutes',summary:'Montana balances its constitutional right to know against individual privacy. The Office of Public Information Requests supports requests for participating state agencies; it does not necessarily cover every local public body. Verify the proper custodian and any privacy exemptions. RESPONSE / PROCEDURAL CHECK: Montana constitutional right-to-know law has specific response requirements under current Title 2, Chapter 6, Part 10; confirm exceptions. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Montana Office of Public Information Requests','https://montanaveba.mt.gov/OPIR/'],['Montana Secretary of State — privacy and right to know','https://sosmt.gov/records/privacy']]},Massachusetts:{law:'Massachusetts Public Records Law, M.G.L. c. 66, § 10 and c. 4, § 7(26)',summary:'Massachusetts uses designated Records Access Officers for public-record requests. The Secretary of the Commonwealth provides a guide and oversees public-record appeals. Exemptions and response obligations depend on the record and custodian. RESPONSE / PROCEDURAL CHECK: Massachusetts generally uses ten-business-day response requirements; agency and municipal appeals can involve the Supervisor of Records. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Massachusetts Secretary — public records resources','https://www.mass.gov/public-records-requests-for-the-secretary-of-the-commonwealth'],['Massachusetts Attorney General — request guidance','https://www.mass.gov/info-details/guidance-for-making-a-public-records-request']]},Michigan:{law:'Michigan Freedom of Information Act, 1976 PA 442, MCL 15.231–15.246',summary:'Michigan FOIA provides access to qualifying public-body records subject to statutory exemptions. Submit a written request to the public body’s FOIA coordinator. Under MCL 15.235, the public body generally must respond within five business days of legal receipt, and may issue one notice extending its response period by up to ten business days. An emailed request ordinarily is legally received one business day after transmission, subject to the statutory spam-folder rule. A response is not necessarily delivery of all requested records. Denial appeals and court review are governed by MCL 15.240, and fee challenges by MCL 15.240a. Preserve the request, receipt evidence, response and any extension notice. This is a public-records route, not a substitute for employee-specific discovery or personnel-access rights. RESPONSE / PROCEDURAL CHECK: Michigan FOIA generally requires a response within five business days, with a single statutory ten-business-day extension; appeals differ for denials and fees. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Michigan Legislature — full FOIA act','https://www.legislature.mi.gov/Laws/MCL?objectName=MCL-ACT-442-OF-1976'],['Michigan Legislature — request requirements','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-233'],['Michigan Legislature — response deadlines','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-235'],['Michigan Attorney General — FOIA FAQ','https://www.michigan.gov/ag/resources/foia'],['Michigan Legislature — appeals','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-240']]},Minnesota:{law:'Minnesota Government Data Practices Act, Minn. Stat. Chapter 13',summary:'Minnesota generally treats government data as public unless classified otherwise by state or federal law. Agencies distinguish public-data requests from requests for data about oneself; data subjects may have different access rights. Fees and request methods vary by agency and type of access. RESPONSE / PROCEDURAL CHECK: Minnesota Data Practices Act generally requires a prompt response; data-subject requests have separate statutory timelines. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Minnesota Office of State Procurement — data requests','https://mn.gov/admin/osp/contact-us/data-requests/'],['Minnesota Department of Health — data practices','https://www.health.mn.gov/data/datapractices']]},Indiana:{law:'Indiana Access to Public Records Act, Ind. Code § 5-14-3',summary:'AUDIT CHECKED 2026-11-19. ELIGIBILITY: Any person may request records. SUBMISSION: IC 5-14-3-3 requires reasonable particularity; an agency may require a written form and law-enforcement recordings need special identifiers. RESPONSE: In-person or telephone refusals can become denials within 24 hours; written requests generally require response within seven calendar days. These are acknowledgment/deemed-denial periods, not universal production deadlines; production must be within a reasonable time. FEES: IC 5-14-3-8 generally bars charges for inspection, ordinary search/review and emailed electronic copies, subject to exceptions. 2026 HEA 1360, effective July 1, permits specified security screening and limited nonresident supplemental fees. EXEMPTIONS: IC 5-14-3-4 protects qualifying personnel, confidential and investigative records; recordings have special rules. REVIEW: Written denials identify exemptions and responsible official; Public Access Counselor complaints generally must be filed within 30 days of denial, and court enforcement is separate. OPEN: Check exact codified 2026 amendment and agency fee schedule.',links:[['Indiana Public Access Counselor complaints','https://www.in.gov/pac/formal-complaints'],['Indiana official response and production FAQ','https://faqs.in.gov/hc/en-us/articles/115005226148-How-long-does-the-agency-have-to-give-me-the-records-I-requested'],['Indiana 2026 HEA 1360 agency explanation','https://www.in.gov/inprs/destinationretirement/posts/2026-legislative-updates/'],['Indiana State Board of Accounts APRA statute summary','https://www.in.gov/sboa/library/home/2025-resource-library/2025-state-agencies/'],['Indiana Public Access Counselor handbook','https://www.in.gov/dA/36bbfdc7b4/pac-handbook.pdf?language_id=1']]},Iowa:{law:'Iowa Code Chapter 22',summary:'AUDIT 2026-11-19. ELIGIBILITY: Every person may inspect and copy public records (§22.2). REQUEST: In person, writing, telephone or electronically (§§22.3-22.4); physical presence cannot be required for copy requests. RESPONSE: No universal fixed production deadline. The 20-calendar-day limit (ordinarily 10 business days) in §22.8(4)(d) applies to deciding whether confidential records may be disclosed, not to every request. Open records should be supplied promptly as feasible. FEES: §22.3 limits copying to attributable actual costs, excludes overhead, and generally encourages only copying charges when fulfillment takes less than 30 minutes; communicate estimated reasonable expenses on receipt. EXEMPTIONS: §22.7 protects peace-officer investigative reports, medical and certain personnel records, with qualified disclosure of basic incident facts; §22.15 concerns notice of potentially public employee discipline. REVIEW: §§22.5 and 22.10 permit judicial enforcement; Iowa Public Information Board complaints generally have a strict 60-day period from violation or reasonable discovery (§23.7), with jurisdictional exclusions. OPEN: Other specific confidentiality laws, fee schedules and court-filing limitations require case review. Not legal advice.',links:[['Iowa Legislature 2026 Chapter 22','https://www.legis.iowa.gov/docs/code/2026/22.pdf'],['Iowa Legislature 2026 Chapter 23','https://www.legis.iowa.gov/docs/code/2026/23.pdf'],['Iowa Public Information Board complaint','https://ipib.iowa.gov/ipib-here-assist/file-complaint'],['Iowa Public Information Board timeliness','https://ipib.iowa.gov/production-record'],['Iowa Public Information Board — Chapter 22','https://ipib.iowa.gov/public-records/chapter-22-examination-public-records-open-records'],['Iowa Public Information Board — public records','https://ipib.iowa.gov/public-records']]},Kansas:{law:'Kansas Open Records Act, K.S.A. 45-215 et seq.',summary:'AUDIT 2026-11-19. ELIGIBILITY: Any person may inspect public records (§45-218), subject to exceptions. REQUEST: Identify existing records and follow agency procedures; written requests and identity proof may be required (§45-220). RESPONSE: Act as soon as possible, no later than the end of the third business day (§45-218(d)); a timely explanation of delay does not equal full production. FEES: Reasonable actual-cost staff and copy fees may be assessed under §45-219; agency schedules vary and there is no general mandatory poverty waiver (Attorney General FAQ). EXEMPTIONS: §45-221(a)(4) covers some personnel records but not names, positions, compensation, employment contracts or service length; §45-221(a)(10) covers criminal investigations subject to a conditional judicial disclosure test; §45-221(a)(55) specifically protects captured license-plate data and records concerning automated license-plate recognition system locations. §45-221(d) generally requires separating open material. REVIEW: Request written denial grounds; contact Attorney General or county/district attorney, or pursue district-court relief under §45-222. OPEN: 2026 HB 2134 changes to fee/exemption provisions need effective-text verification, plus case-specific court deadlines. Not legal advice.',links:[['Kansas Legislature 2026 section 45-218','https://www.kslegislature.gov/b2025_26/laws/045_000_0000_chapter/045_002_0000_article/045_002_0018_section/045_002_0018_k/'],['Kansas Legislature 2026 section 45-221','https://www.kslegislature.gov/b2025_26/laws/045_000_0000_chapter/045_002_0000_article/045_002_0021_section/045_002_0021_k/'],['Kansas Legislature 2026 section 45-222','https://www.kslegislature.gov/b2025_26/laws/045_000_0000_chapter/045_002_0000_article/045_002_0022_section/045_002_0022_k/'],['Kansas Attorney General FAQ','https://www.ag.ks.gov/divisions/administration/open-government/kora-faq'],['Kansas Attorney General KORA FAQ','https://www.ag.ks.gov/divisions/administration/open-government/kora-faq'],['Kansas Attorney General resources','https://www.ag.ks.gov/divisions/administration/open-government/resources']]},Kentucky:{law:'Kentucky Open Records Act, KRS 61.870–61.884',summary:'AUDIT CHECKED 2026-11-19 (Kentucky Attorney General 26-ORD-216, KRS 61.870–61.884, 40 KAR 1:030). ELIGIBILITY: KRS 61.870(10) defines Kentucky resident broadly, including residents, Kentucky workers and property owners, qualifying businesses, authorized representatives, and defined news organizations; do not treat physical domicile as the sole qualification. REQUEST: Send a written request identifying existing records to the official custodian by permitted means. KRS 61.872(2)(c) prohibits requiring a particular request form; Kentucky AG decision 26-ORD-216 confirms this. RESPONSE: Under KRS 61.880(1), written grant/denial determination is due within five business days excluding weekends and legal holidays, not necessarily complete production. Under KRS 61.872(5), delay when records are in use, storage, or otherwise unavailable requires a detailed explanation and earliest availability date. FEES: KRS 61.874 regulates reasonable copying charges and commercial use; inspect the custodian schedule and statutory limits. EXEMPTIONS: KRS 61.878 includes privacy, confidential personnel-related information and law-enforcement investigative material when statutory criteria are met; criminal-history records may also implicate KRS 17.150. REVIEW: A written denial or improper delay/fees may be taken to the Kentucky Attorney General under KRS 61.880; an AG decision can be appealed in circuit court within 30 days. KRS 61.882 also governs judicial enforcement. OPEN: Verify specific fee rates and record-category exemptions for the target custodian; no universal production deadline should be promised.',links:[['Kentucky AG — 2026 decision on residency, forms and appeals','https://www.ag.ky.gov/Resources/orom/2026/26-ORD-216.pdf'],['Kentucky legislature — AG appeal regulation 40 KAR 1:030','https://apps.legislature.ky.gov/law/kar/titles/040/001/030/'],['Kentucky AG — 2026 delay decision','https://www.ag.ky.gov/Resources/orom/2026/26-ORD-137.pdf'],['Kentucky Attorney General — Open Records and Open Meetings','https://www.ag.ky.gov/Resources/orom/Pages/default.aspx'],['Kentucky Attorney General — request instructions','https://www.ag.ky.gov/Contact-Us/Pages/Open-Records-Requests.aspx']]},Louisiana:{law:'Louisiana Public Records Law, La. R.S. 44:1 et seq.',summary:'AUDIT CHECKED 2026-11-19 (Louisiana Legislative Auditor Public Records Law FAQ revised August 2026; La. R.S. 44:1–44:42). ELIGIBILITY: Under R.S. 44:31, adults may inspect and copy records and any person may obtain copies, subject to restrictions in R.S. 44:31.1 for certain convicted prisoners; requests to the Governor’s office are subject to a Louisiana residency restriction. REQUEST: Direct a reasonably described request to the records custodian; in-person, written and electronic requests may be used. R.S. 44:33.1 requires public custodian contact information. RESPONSE: R.S. 44:33 generally requires immediate access to an available, nonexempt record; when a record is in active use, written certification must give a date and hour within three business days. R.S. 44:32 requires written explanation citing legal authority when withheld; under R.S. 44:35, five business days without a written determination or reasonable time estimate can trigger court remedies. Five days is NOT a universal production deadline. FEES: Inspection during regular hours generally is free; copies may be charged under a published reasonable local schedule or state uniform schedule. Discretionary reductions or waivers may apply for indigent residents or public-purpose use. EXEMPTIONS: R.S. 44:3 governs certain criminal investigative records; R.S. 44:11 protects specified public employee personal and medical data; R.S. 44:4.1 incorporates other confidentiality provisions. REVIEW: R.S. 44:35 permits mandamus, injunctive or declaratory relief in the district court of the parish where the custodian’s office is located; fees, damages and penalties are fact-dependent. OPEN: Confirm specialized law-enforcement record exemptions and exact agency copy fee schedule before requesting.',links:[['Louisiana Legislative Auditor — Public Records Law FAQ revised August 2026','https://app.lla.state.la.us/llala.nsf/7C469838E7BC1C5186257AC2004F6279/$FILE/Public%20Records%20Law%20FAQ.pdf'],['Louisiana Legislative Auditor — records request guidance','https://www.lla.la.gov/public-records-request'],['Louisiana Legislature — R.S. 44:31','https://legis.la.gov/Legis/LawPrint.aspx?d=99688'],['Louisiana Legislature — R.S. 44:31.1','https://www.legis.la.gov/Legis/LawPrint.aspx?d=99689']]},Florida:{law:'Florida Constitution Art. I § 24; Florida Statutes Chapter 119',summary:'ELIGIBILITY: Any person may request nonexempt Florida state, county and municipal records under Fla. Const. art. I, § 24 and Fla. Stat. § 119.01. SUBMISSION: Request existing records from the agency custodian; identify the records and retain a dated copy. RESPONSE: § 119.07(1) requires inspection and copying at reasonable times under reasonable conditions, with reasonable time for retrieval and redaction; there is no universal fixed five- or ten-day production deadline. FEES: § 119.07(4) generally allows actual duplication costs or specified statutory copy charges; extensive clerical or supervisory assistance or extensive information technology use can justify a special service charge based on actual costs. EXEMPTIONS: § 119.071 includes active criminal investigative and intelligence information and specified law-enforcement personnel privacy and safety protections; segregate nonexempt portions under § 119.07(1)(d). DENIAL: § 119.07(1)(e) requires the custodian to state the basis for an exemption, citing the statute if requested. REVIEW: Judicial enforcement under §§ 119.11–119.12; attorney-fee awards generally require written notice identifying the request at least five business days before suit, with a posted-contact-information exception; no automatic damages under § 119.12. SOURCE AUDIT 2026-11-19: 2026 Florida Legislature Chapter 119 and § 119.12 checked. OPEN: Agency-specific exemptions, service-fee calculations and any case-specific filing limits require separate confirmation.',links:[['Florida Legislature — 2026 Chapter 119','https://www.leg.state.fl.us/Statutes/index.cfm?App_mode=Display_Statute&URL=0100-0199/0119/0119.html'],['Florida Legislature — § 119.12 attorney fees','https://www.leg.state.fl.us/Statutes/index.cfm?App_mode=Display_Statute&URL=0100-0199/0119/Sections/0119.12.html'],['Florida Attorney General Sunshine Manual','https://www.myfloridalegal.com/sites/default/files/government-in-the-sunshine-manual.pdf']]},Georgia:{law:'Georgia Open Records Act, O.C.G.A. §§ 50-18-70 et seq.',summary:'ELIGIBILITY: Georgia Open Records Act, O.C.G.A. §§ 50-18-70–77, generally permits requests for nonexempt agency records, including records held by private contractors acting for public agencies. SUBMISSION: Ask the designated custodian; oral requests may be accepted, but written requests are needed for judicial enforcement, so preserve the date and wording. RESPONSE: Under §§ 50-18-71 and 50-18-72(h), agencies generally produce records within three business days unless exceptional circumstances prevent production; if delayed, provide a written timetable, cost estimate and specific statutory withholding basis within that period. FEES: § 50-18-71 allows reasonable direct search, retrieval and redaction labor costs capped by the lowest-paid qualified full-time employee; first 15 minutes free; ordinary paper copies generally capped at 25 cents per page. Prepayment is limited by statutory conditions, including estimates over $500 or certain prior unpaid charges. EXEMPTIONS: § 50-18-72 covers pending investigations and specified personal information; redact protected material rather than withhold an entire otherwise releasable record. REVIEW: Attorney General open-government complaint or mediation may help; court enforcement is available under § 50-18-73. Do not apply Open Meetings Act litigation deadlines to Open Records Act requests. SOURCE AUDIT 2026-11-19: Georgia Attorney General request guidance, official FAQ and published legal interpretations checked. OPEN: Exact limitations period for particular court claims and changes to police-record exceptions need independent confirmation.',links:[['Georgia Attorney General — open government FAQ','https://law.georgia.gov/key-issues/open-government/faq-open-government'],['Georgia Attorney General — how to request','https://law.georgia.gov/key-issues/open-government/how-make-open-records-request'],['Georgia Attorney General — law enforcement investigation opinion','https://law.georgia.gov/opinions/97-20'],['Georgia Attorney General — how to request','https://law.georgia.gov/key-issues/open-government/how-make-open-records-request'],['Georgia Governor — records overview','https://gov.georgia.gov/contact-us/open-records-request']]},Hawaii:{law:'Uniform Information Practices Act (Modified), Hawaii Revised Statutes Chapter 92F',summary:'AUDIT 2026-11-19: Any person may request records under HRS chapter 92F. Send a written formal request to the holding agency with contact information and records description. HAR 2-71-13: fully public records generally disclosed within 10 business days; partially exempt records receive notice within 10 business days and public portions within 5 business days after notice or required prepayment. Extenuating circumstances allow acknowledgment within 10 days and notice by 20 business days. HAR 2-71-31 generally charges $2.50 per 15 minutes search and $5 per 15 minutes review, first $30 waived; alternative $60 public-interest waiver requires qualifying dissemination facts. Copying costs separate. HRS 92F-13 protects privacy and other confidential information, including record-specific public-safety exceptions. Written OIP denial appeal generally due within one year under HAR 2-73; court review under HRS 92F-15 does not require OIP exhaustion. SOURCES: https://ags.hawaii.gov/oip/uipa-rules/ ; https://ags.hawaii.gov/oip/guide-to-oip-appeals/ ; https://ags.hawaii.gov/oip/how-to-request-a-record/ . OPEN: Proposed 2026 fee-rule changes are not yet treated as effective; monitor https://ags.hawaii.gov/oip/news-from-oip-oip-to-hold-public-hearing-on-proposed-new-administrative-rules/ .',links:[['Hawaii Office of Information Practices — UIPA','https://ags.hawaii.gov/oip/uipa-/'],['Hawaii agency — submitting a UIPA request','https://budget.hawaii.gov/contact/uniform-information-practices-act/']]},Idaho:{law:'Idaho Public Records Act, Idaho Code Title 74, Chapter 1',summary:'AUDIT 2026-11-19: Idaho Code Title 74 ch. 1 allows residents and nonresidents to request existing public records from designated custodians; label the submission a public-records request under § 74-103. Resident requests generally receive grant/denial within 3 working days and, with written delay notice, production within 10 working days. Nonresident requests by persons not employed by residents generally have 21 days for grant/denial and up to 35 days for production after notice; electronic conversion can alter timing. § 74-102 generally provides Idaho residents the first two processing hours and 100 pages without charge, subject to statutory conditions; additional permissible labor and copying charges apply. §§ 74-104 through 74-111 contain law-enforcement, personnel, medical and privacy exemptions requiring record-specific review. Written denial must cite law and remedies. § 74-115 generally permits a district-court petition within 180 days after denial mailing; no mandatory internal appeal exhaustion. SOURCES: Idaho AG 2026 manual https://www.ag.idaho.gov/content/uploads/2026/07/PublicRecordsLaw.pdf ; AG guidance https://www.ag.idaho.gov/office-resources/public-records/ ; agency procedures https://adm.idaho.gov/public-record-request/ . OPEN: Check agency-specific fee schedules and particular record exceptions.',links:[['Idaho Attorney General — public records','https://www.ag.idaho.gov/office-resources/public-records/'],['Idaho Attorney General — 2026 manual','https://www.ag.idaho.gov/content/uploads/2026/07/PublicRecordsLaw.pdf']]},Illinois:{law:'Illinois Freedom of Information Act, 5 ILCS 140',summary:'AUDIT CHECKED 2026-11-19. ELIGIBILITY: Any person can request existing public records. SUBMISSION: Send an identifiable request to the public body FOIA officer; an agency cannot mandate its own form or a reason except for commercial use or fee-waiver decisions (5 ILCS 140/3). RESPONSE: Ordinary noncommercial requests generally require compliance or denial within five business days; an enumerated reason permits a written five-business-day extension. Commercial, recurrent and voluminous requests differ. FEES: Section 6 generally makes the first 50 standard black-and-white pages free and limits further pages to $0.15 each; ordinary search/review labor is not chargeable, subject to special categories. EXEMPTIONS: Sections 7 and 7.5 protect qualifying privacy, investigative and other confidential records, including special body-camera protections; redact and release segregable nonexempt material. REVIEW: Section 9.5 generally provides 60 days for PAC review after final denial; section 11 provides judicial enforcement. OPEN: Check body-camera disclosure exceptions and judicial deadlines for specific cases.',links:[['Illinois Legislature section 3 request and response','https://www.ilga.gov/legislation/ilcs/fulltext?DocName=000501400K3'],['Illinois Legislature section 6 fees','https://www.ilga.gov/legislation/ilcs/fulltext?DocName=000501400K6'],['Illinois Legislature section 7.5 exemptions','https://www.ilga.gov/legislation/ilcs/fulltext?DocName=000501400K7.5'],['Illinois Attorney General PAC guide','https://illinoisattorneygeneral.gov/Page-Attachments/FOIAPAC/PACGuide.pdf'],['Illinois Attorney General — Public Access Counselor','https://illinoisattorneygeneral.gov/open-and-honest-government/pac/'],['Illinois General Assembly — FOIA review provision','https://www.ilga.gov/documents/legislation/ilcs/documents/000501400K9.5.htm']]},Arkansas:{law:'Arkansas Freedom of Information Act, Ark. Code Ann. §§ 25-19-101 et seq.',summary:'ELIGIBILITY: Arkansas FOIA access to public records is generally for Arkansas citizens, subject to statutory interpretation and exceptions. SUBMISSION: Direct a sufficiently specific request to the records custodian; oral, email, telephone and written requests may be accepted. RESPONSE: Records are generally available immediately unless in active use or storage, when they should generally be made available within three working days. Special 24-hour decision provisions apply to personnel and employee-evaluation records. FEES: The custodian generally may charge actual reproduction costs plus mailing, not a general search fee. EXEMPTIONS: Personnel, employee evaluations, undisclosed law-enforcement investigations and other protected information have specific statutory treatment. REVIEW: Judicial enforcement is available under the FOIA; check standing, notice and procedural requirements before litigation. AUDIT: Arkansas Attorney General 21st-edition FOIA handbook and official AG overview checked November 18, 2026.',links:[['Arkansas Attorney General FOIA overview','https://arkansasag.gov/divisions/opinions-foia/arkansas-freedom-of-information-act/'],['Arkansas FOIA handbook (2025)','https://healthy.arkansas.gov/wp-content/uploads/2025-FOIA-Handbook-21st-Edition-ver4.pdf']]},California:{law:'California Public Records Act, Cal. Gov. Code §§ 7920.000–7930.215',summary:'ELIGIBILITY: Any person may request disclosable state or local agency records under the California Public Records Act, Gov. Code § 7920.000 et seq. SUBMISSION: Identify records and send a request to the agency holding them; agencies generally must assist in identifying responsive records. RESPONSE: § 7922.535 requires an initial determination, not necessarily completed production, within the statutory period; the previously codified rule was ten calendar days with a possible 14-calendar-day unusual-circumstances extension. IMPORTANT CURRENT-LAW ALERT: 2026 legislative materials for AB 1821 describe a change to ten BUSINESS days and a 14-business-day extension; verify enactment and operative date directly before calculating a deadline. FEES: Ordinary copies generally involve direct duplication costs under § 7922.530, with additional rules for electronic extraction. EXEMPTIONS: § 7922.000 and specific law-enforcement, personnel, privacy and other exemptions can apply. REVIEW: Denial may be challenged through court proceedings under the CPRA; confirm current statutory remedy provisions. AUDIT STATUS: Primary statute and 2026 legislative change identified; operative-date verification remains OPEN.',links:[['California DOJ public records guidance','https://oag.ca.gov/consumers/general/pra'],['California DOJ PRA FAQ','https://oag.ca.gov/consumers/general/pra_faq'],['California DOJ guidelines PDF','https://oag.ca.gov/system/files/media/pra-guidelines.pdf']]},Colorado:{law:'Colorado Open Records Act, C.R.S. §§ 24-72-201–206',summary:'ELIGIBILITY/SUBMISSION: Colorado Open Records Act (CORA), C.R.S. §§ 24-72-201 et seq., generally covers public records, but criminal justice records may instead fall under the Colorado Criminal Justice Records Act (CCJRA). Send an identifiable request to the custodian following the agency’s submission rules. RESPONSE: Under § 24-72-203(3)(b), records not readily available are presumptively available within three working days; qualifying extenuating circumstances can add up to seven working days with timely written notice. FEES: Research, retrieval and copying fees are governed by § 24-72-205 and published agency schedules; the first hour of research and retrieval is generally free. EXEMPTIONS: Statutory confidential, privileged, personnel and criminal-justice information may be excluded or governed by CCJRA. REVIEW: Request a written basis for denial; CORA enforcement procedures are set out in § 24-72-204(5), with prerequisites and timing that must be checked before filing. AUDIT: Colorado Attorney General CORA/CCJRA guidance, Department of Revenue guidance and § 24-72-203 checked November 18, 2026.',links:[['Colorado Department of Revenue CORA guidance','https://cdor.colorado.gov/cora'],['Colorado Attorney General CORA and CCJRA','https://coag.gov/media-center/colorado-open-records-act-cora/'],['Colorado legislative CORA summary','https://content.leg.colorado.gov/sites/default/files/colorado-open-records-act-cora-colorado-law-summary-accessible.pdf']]},Connecticut:{law:'Connecticut Freedom of Information Act, Conn. Gen. Stat. §§ 1-200 et seq.',summary:'ELIGIBILITY: Every person may inspect public agency records under Conn. Gen. Stat. § 1-210(a), subject to statutory exemptions. SUBMISSION: Request existing records from the agency holding them; the FOI Commission explains that an agency may require a written request for copies but not simply to inspect. RESPONSE: Records must be available promptly; § 1-206(a) generally requires written denial within four business days, with a ten-business-day exception for certain § 1-214 personnel-related requests. Noncompliance within the applicable period is deemed a denial; these are NOT universal production deadlines. FEES: Under § 1-212, ordinary state-agency copies generally cost no more than $0.25 per page and municipal copies $0.50 per page, with statutory exceptions and electronic-media rules. EXEMPTIONS: § 1-210(b) includes specified law-enforcement, privacy, personnel and other exceptions; § 1-214 imposes special employee-notice rules in some cases. APPEAL: § 1-206(b)(1) generally requires a written complaint to the Freedom of Information Commission within 30 days after denial; confirm deemed-denial accrual and any special circumstances. PRIMARY SOURCES CHECKED 2026-11-19: Connecticut General Assembly 2026 supplement to Chapter 14; Connecticut FOI Commission guidance and FOI Act. OPEN: Agency-specific copying formats and record-specific exemptions must be verified.',links:[['Connecticut General Assembly Chapter 14','https://www.cga.ct.gov/current/pub/chap_014.htm'],['Connecticut 2026 statutory supplement','https://www.cga.ct.gov/2026/sup/chap_014.htm'],['Connecticut Freedom of Information Commission','https://portal.ct.gov/FOI/'],['Connecticut FOI Commission — appeal and fee guidance','https://portal.ct.gov/FOI/Common-Elements/Template-V4/How-Do-I_B']]},Delaware:{law:'Delaware Freedom of Information Act, 29 Del. C. §§ 10001–10008',summary:'ELIGIBILITY: Delaware FOIA § 10003 uses citizen access language; nonresident eligibility and case law should be checked before relying on the statute for a particular requester. SUBMISSION: Under § 10003(f), send a written request to the public body by email, mail, fax, in person or online; the standardized form is optional, and records must be described sufficiently for a reasonable search. RESPONSE: § 10003(h) requires an answer as soon as possible and within 15 business days, either access, reasoned denial or a permitted extension with a good-faith estimate for voluminous records, legal review or archived/stored records. This is not a guaranteed production deadline. FEES: § 10003(m) generally provides the first 20 standard black-and-white pages free, then $0.10 per sheet; administrative fees apply only after the first hour and require an itemized estimate, with other statutory/local-code rules possible. EXEMPTIONS: § 10002 excludes specified investigative, personnel, medical, pending-litigation and other protected records. APPEAL: Under § 10005(b), records-denial lawsuits generally have a 60-day deadline; for state bodies the Attorney General is obligated to represent, a petition to the Chief Deputy within 60 days is mandatory before specified Superior Court review, with a further 60-day appeal period after AG decision. Other AG petitions and remedies differ. PRIMARY SOURCES CHECKED 2026-11-19: Delaware Code Chapter 100 §§ 10002, 10003, 10005; Delaware DOJ Open Government guidance and March 10, 2026 FOIA opinion. OPEN: Apply the correct agency type and jurisdiction to appeal route; specific exemptions and local fees require record-specific review.',links:[['Delaware Code — current FOIA chapter','https://delcode.delaware.gov/title29/c100/'],['Delaware statewide FOIA portal','https://delaware.gov/freedom-of-information-act/'],['Delaware Department of Justice open government','https://attorneygeneral.delaware.gov/executive/open-government/']]},Alaska:{law:'Alaska Statutes §§ 40.25.110–40.25.125',summary:'ELIGIBILITY: Alaska’s Public Records Act covers state and local agencies, but executive-branch regulations do not automatically govern all municipalities, the legislature or courts. SUBMISSION: Make a clear request to the custodian, identifying existing records; electronic-services requests may have separate rules under AS 40.25.115. RESPONSE: For executive-branch requests under AS 40.25.110, 2 AAC 96.325 generally allows an initial 10-working-day response and a 10-working-day extension, with additional extensions possible by agreement or Attorney General approval; response is not always complete production. FEES: Recoverable search and copying charges may require prepayment under 2 AAC 96.360; public-interest fee relief is addressed in 2 AAC 96.370. EXEMPTIONS: Statutory confidential information and protected records are excluded; agencies generally need not create new records. APPEAL: Under 2 AAC 96.340, an executive-branch administrative denial appeal generally must be mailed or hand-delivered to the agency head within 60 working days. AUDIT: Alaska Department of Law APRA guidance and executive-branch regulations reviewed November 18, 2026.',links:[['Alaska Department of Law — APRA guide','https://law.alaska.gov/doclibrary/APRA.html'],['Alaska Legislature — statutes','https://www.akleg.gov/basis/statutes.asp#40.25.110']]},Arizona:{law:'Arizona Revised Statutes §§ 39-121–39-121.03',summary:'ELIGIBILITY: Any person may inspect public records under A.R.S. § 39-121. SUBMISSION: Direct a reasonably specific request to the officer or agency holding the records; noncommercial requests generally need not be written, but document a denial in writing. RESPONSE: Records must be furnished promptly; Arizona has no universal fixed numerical response deadline, and failure to respond promptly may be treated as a denial under § 39-121.01(E). FEES: Inspection and copies differ; reasonable copy fees may apply, and § 39-121.03 imposes additional rules for commercial use. EXEMPTIONS: Confidentiality statutes, privacy, public-safety and other recognized interests may justify withholding; some law-enforcement and victim records have specific protections. REVIEW: § 39-121.02(A) allows a denied requester to seek a special action in superior court without a required administrative appeal; § 39-121.02(B) addresses possible attorney fees and costs for substantially prevailing requesters. AUDIT: Arizona Legislature §§ 39-121–39-121.03 and Ombudsman guidance reviewed November 18, 2026.',links:[['Arizona Legislature — Title 39','https://www.azleg.gov/arsDetail/?title=39'],['Arizona Ombudsman — public records law','https://www.azoca.gov/arizona-public-records-law/'],['Arizona Ombudsman — public records FAQ','https://www.azoca.gov/faqs/faqs-public-access-laws/']]},Alabama:{law:'Alabama Code § 36-12-40 and §§ 36-12-43 through 36-12-45',summary:'ELIGIBILITY: Alabama’s public-records law generally grants access to Alabama residents; an officer may require reasonable proof of residency and may elect to respond to nonresidents. SUBMISSION: Identify records with reasonable specificity; the officer may require its published form or written procedure. RESPONSE: Under § 36-12-44, a proper standard request must be acknowledged within 10 business days and substantively fulfilled or denied within 15 business days after acknowledgment, subject to written 15-business-day extensions and statutory tolling. Time-intensive requests have different fee and 45-business-day procedures. FEES: Reasonable fees and prepayment may be required; inspect the particular agency’s published schedule. EXEMPTIONS: Privileged, confidential and other legally protected records may be withheld; the statute does not require creation of new records. DENIAL/REMEDY: § 36-12-44 establishes conditional presumptions of denial, including 30-business-day/60-calendar-day thresholds for standard requests; court enforcement and applicable limitations should be independently checked before filing. AUDIT: Primary source § 36-12-44 and Alabama Secretary of State procedures reviewed November 18, 2026.',links:[['Official statute § 36-12-40','https://alison.legislature.state.al.us/code-of-alabama?section=36-12-40'],['Official request procedures § 36-12-44','https://alison.legislature.state.al.us/code-of-alabama?section=36-12-44'],['Alabama Secretary of State request instructions','https://www.sos.alabama.gov/public-records-request']]}};
 const verifiedPanel=document.createElement('section');verifiedPanel.className='card';verifiedPanel.id='verified-state';verifiedPanel.setAttribute('aria-label','State public records research and source links');panel.insertBefore(verifiedPanel,draft.previousElementSibling);
 function showVerified(name){verifiedPanel.replaceChildren();const info=verified[name];if(!info){verifiedPanel.hidden=true;return;}verifiedPanel.hidden=false;const title=document.createElement('h3');title.textContent='State public-records law: '+info.law;verifiedPanel.appendChild(title);const p=document.createElement('p');p.textContent=info.summary;verifiedPanel.appendChild(p);for(const [label,url] of info.links){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;a.style.display='block';a.style.marginBottom='8px';verifiedPanel.appendChild(a);}const disclaimer=document.createElement('p');disclaimer.textContent=independentlyAuditedStates.has(name)?'Primary-source statutory audit completed 2026-11-19 for the listed sections. Agency rules and record-specific exceptions may still affect outcomes.':enhancedReviewStates.has(name)?'Expanded procedural research, not independently audited for every exception or deadline. Confirm current primary sources before relying on a rule.':'Preliminary research. Fees, exemptions, appeal routes and deadlines still require source-by-source verification. Not attorney-reviewed legal advice.';verifiedPanel.appendChild(disclaimer);const detail=document.createElement('a');detail.href='https://www.rcfp.org/open-government-guide/'+name.toLowerCase().replace(/\s+/g,'-')+'/';detail.target='_blank';detail.rel='noopener noreferrer';detail.textContent='Read the detailed '+name+' open-records guide (eligibility, exemptions, fees and appeals)';detail.style.display='block';verifiedPanel.appendChild(detail);}

 const slug=name=>name.toLowerCase().replace(/\s+/g,'-');
 const sources='Review the state-specific Reporters Committee guide linked below, then verify current requirements against official statutes and the receiving agency’s instructions.';
 function template(name){return 'PUBLIC RECORDS REQUEST — '+name.toUpperCase()+' (GENERAL STARTING DRAFT; NOT LEGALLY REVIEWED)\n\nDate: [DATE]\nTo: [PUBLIC AGENCY / RECORDS CUSTODIAN]\nAgency address or approved request channel: [ADDRESS / PORTAL]\n\nSubject: Request for access to public records\n\nHello,\n\nI request access to the following identifiable public records maintained by your agency, to the extent disclosure is authorized by applicable '+name+' law:\n\n[DESCRIBE SPECIFIC RECORDS, APPROXIMATE DATES, OFFICES, AND SEARCH TERMS]\n\nPlease let me know whether the records are available electronically and whether any fees apply before processing if the cost will exceed [AMOUNT]. If any responsive material is withheld, please identify the applicable legal basis and provide any reasonably segregable disclosable portions where required by law.\n\nPlease advise me of any agency-specific submission requirements. I understand that requester eligibility, response periods, exemptions, fees and review rights vary and must be independently verified.\n\nThank you,\n[REQUESTER NAME IF REQUIRED]\n[REPLY CONTACT / DELIVERY METHOD]\n\nIMPORTANT: Verify '+name+' requester eligibility, public-records statute, exemptions, response periods and agency rules before sending. Do not request or disclose restricted personnel, criminal justice, medical, privileged or confidential information without authorization.';}
 state.addEventListener('change',()=>{const name=state.value;if(!name){note.textContent='Choose a state to see resource availability.';panel.hidden=true;return;}panel.hidden=false;showVerified(name);if(guideLink){guideLink.href=rcfp+slug(name)+'/';guideLink.textContent=name+' open-government guide (RCFP)';}heading.textContent=name+' — public-records starting resources';intro.textContent=name==='Michigan'?'Michigan: the separate Michigan FOIA Desk offers a locally generated draft. The general template below is also available. '+sources:'Use the resources below to locate '+name+' public-records law, then adapt the free blank request letter. '+sources;note.textContent='Showing '+name+' resources below. Any state summary is preliminary research, not comprehensive legal verification. Check current official sources and deadlines.';draft.textContent=template(name);panel.scrollIntoView({behavior:'smooth',block:'start'});});
 download.addEventListener('click',()=>{if(!state.value)return;const blob=new Blob([draft.textContent],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='the-shield-'+state.value.toLowerCase().replace(/\s+/g,'-')+'-public-records-request.txt';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);});
 print.addEventListener('click',()=>{if(!state.value)return;const w=window.open('','_blank');if(!w){note.textContent='Pop-up blocked. Use the download button and print the saved text file.';return;}const pre=w.document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.style.fontFamily='serif';pre.style.fontSize='14px';pre.textContent=draft.textContent;w.document.body.appendChild(pre);w.document.title='THE SHIELD — '+state.value+' blank public records request';w.print();});
})();
